package main

import (
	"fmt"
	"sort"
)

type person struct {
	Name string
	Age  int
}

func main() {
	people := []person{{"carol", 30}, {"alice", 25}, {"bob", 30}, {"dave", 25}}
	sort.Slice(people, func(i, j int) bool { return people[i].Name < people[j].Name })
	fmt.Println(people)
	sort.SliceStable(people, func(i, j int) bool { return people[i].Age < people[j].Age })
	fmt.Println(people)
	fmt.Println(sort.SliceIsSorted(people, func(i, j int) bool { return people[i].Age < people[j].Age }))
	nums := []int{9, 3, 7, 1}
	sort.Slice(nums, func(i, j int) bool { return nums[i] > nums[j] })
	fmt.Println(nums)
	strs := []string{"pear", "fig", "apple"}
	sort.Slice(strs, func(i, j int) bool { return len(strs[i]) < len(strs[j]) })
	fmt.Println(strs)
	fmt.Println(sort.SearchInts([]int{1, 3, 5, 7}, 5), sort.SearchInts([]int{1, 3, 5, 7}, 4))
	empty := []int{}
	sort.Slice(empty, func(i, j int) bool { return true })
	fmt.Println(len(empty))
}

