package m

func Clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

package m

import "testing"

func wantEq(t *testing.T, got, want int) {
	t.Helper()
	if got != want {
		t.Errorf("%s: got %d want %d", t.Name(), got, want)
	}
}

func TestClampName(t *testing.T) {
	if t.Name() != "TestClampName" {
		t.Fatalf("unexpected name %q", t.Name())
	}
	wantEq(t, Clamp(5, 0, 10), 5)
	wantEq(t, Clamp(-3, 0, 10), 0)
	wantEq(t, Clamp(42, 0, 10), 10)
}

func TestSubtestNames(t *testing.T) {
	t.Run("low", func(t *testing.T) {
		wantEq(t, Clamp(-1, 2, 4), 2)
		if t.Name() != "TestSubtestNames/low" {
			t.Errorf("name %q", t.Name())
		}
	})
	t.Run("high", func(t *testing.T) {
		wantEq(t, Clamp(9, 2, 4), 4)
		if t.Failed() {
			t.Error("unexpectedly failed")
		}
	})
}

func TestFailNowStops(t *testing.T) {
	// FailNow stops the calling test, but its deferred functions still run and
	// the rest of the run continues.
	after := false
	ok := t.Run("stops", func(t *testing.T) {
		defer func() { t.Log("deferred still runs") }()
		if Clamp(9, 0, 2) == 2 {
			t.FailNow()
		}
		after = true
	})
	if ok {
		t.Error("subtest should have failed")
	}
	if after {
		t.Error("statements after FailNow must not run")
	}
	if !t.Failed() {
		t.Error("a failing subtest must fail its parent")
	}
}

func TestSkipped(t *testing.T) {
	t.Skip("nothing to do here")
	t.Error("unreachable after Skip")
}

func TestSkipf(t *testing.T) {
	t.Skipf("skipping %s at %d", "this", 7)
	t.Error("unreachable after Skipf")
}

func TestSkipNow(t *testing.T) {
	if Clamp(0, 0, 1) == 0 {
		t.SkipNow()
	}
	t.Error("unreachable after SkipNow")
}

