//go:noinline
func f16(p *uint8, b []byte) {
	_ = b[1]            // bounds check
	x := *p             // load a byte
	y := uint16(x)      // zero extend to 16 bits
	b[0] = byte(y >> 8) // compute ROLW
	b[1] = byte(y)
	nop()               // spill/restore ROLW
	b[0] = byte(y >> 8) // use ROLW
	b[1] = byte(y)
}

//go:noinline
func f32(p *uint8, b []byte) {
	_ = b[3]             // bounds check
	x := *p              // load a byte
	y := uint32(x)       // zero extend to 32 bits
	b[0] = byte(y >> 24) // compute ROLL
	b[1] = byte(y >> 16)
	b[2] = byte(y >> 8)
	b[3] = byte(y)
	nop()                // spill/restore ROLL
	b[0] = byte(y >> 24) // use ROLL
	b[1] = byte(y >> 16)
	b[2] = byte(y >> 8)
	b[3] = byte(y)
}

//go:noinline
func f64(p *uint8, b []byte) {
	_ = b[7]             // bounds check
	x := *p              // load a byte
	y := uint64(x)       // zero extend to 64 bits
	b[0] = byte(y >> 56) // compute ROLQ
	b[1] = byte(y >> 48)
	b[2] = byte(y >> 40)
	b[3] = byte(y >> 32)
	b[4] = byte(y >> 24)
	b[5] = byte(y >> 16)
	b[6] = byte(y >> 8)
	b[7] = byte(y)
	nop()                // spill/restore ROLQ
	b[0] = byte(y >> 56) // use ROLQ
	b[1] = byte(y >> 48)
	b[2] = byte(y >> 40)
	b[3] = byte(y >> 32)
	b[4] = byte(y >> 24)
	b[5] = byte(y >> 16)
	b[6] = byte(y >> 8)
	b[7] = byte(y)
}

