package main

import (
	"fmt"
	"runtime"
)

func churn(n int) int {
	total := 0
	for i := 0; i < n; i++ {
		b := make([]byte, 512)
		b[0] = byte(i)
		total += int(b[0])
	}
	return total
}

func main() {
	var a, b runtime.MemStats
	runtime.ReadMemStats(&a)
	churn(2000)
	runtime.GC()
	runtime.ReadMemStats(&b)
	fmt.Println("collections advanced:", b.NumGC > a.NumGC)
	fmt.Println("pause time accrued:", b.PauseTotalNs > 0)
	fmt.Println("pause total is monotonic:", b.PauseTotalNs >= a.PauseTotalNs)
	runtime.GC()
	var c runtime.MemStats
	runtime.ReadMemStats(&c)
	fmt.Println("second cycle counted:", c.NumGC > b.NumGC, c.PauseTotalNs >= b.PauseTotalNs)
}

